package org.jiuyun.input;
import org.json.*;import java.util.*;
public final class Shuangpin {
 public static void validate(JSONObject s)throws JSONException{if(s.getString("name").trim().isEmpty()||s.getString("name").length()>30)throw new JSONException("Invalid name");String rule=s.getString("zeroRule");if(!Arrays.asList("natural","prefix","first-letter").contains(rule))throw new JSONException("Invalid zero rule");if(!s.getString("zeroKey").matches("[a-z;]"))throw new JSONException("Invalid zero key");for(String group:new String[]{"initials","finals"}){JSONObject map=s.getJSONObject(group);Iterator<String> it=map.keys();while(it.hasNext())if(!map.getString(it.next()).matches("[a-z;]"))throw new JSONException("Use one letter or semicolon");}for(String k:"b p m f d t n l g k h j q x r z c s y w zh ch sh".split(" "))s.getJSONObject("initials").getString(k);for(String k:"a o e i u v ai an ang ao ei en eng er ia ian iang iao ie in ing iong iu ong ou ua uai uan uang ue ui un uo ve".split(" "))s.getJSONObject("finals").getString(k);}
 public static List<String> encode(String pinyin,JSONObject s){List<String> result=new ArrayList<>();result.add("");for(String syllable:pinyin.split("[ ']+")){List<String> part=new ArrayList<>();JSONObject overrides=s.optJSONObject("overrides");JSONArray alias=overrides==null?null:overrides.optJSONArray(syllable);if(alias!=null){for(int i=0;i<alias.length();i++)part.add(alias.optString(i));}else{String initial="";java.util.regex.Matcher m=java.util.regex.Pattern.compile("^(zh|ch|sh|[bpmfdtnlgkhjqxrzcsyw])").matcher(syllable);if(m.find())initial=m.group(1);JSONObject finals=s.optJSONObject("finals"),initials=s.optJSONObject("initials");String f=finals==null?"":finals.optString(syllable.substring(initial.length()));if(f.isEmpty())return Collections.emptyList();String code;if(!initial.isEmpty())code=initials.optString(initial)+f;else if(s.optString("zeroRule").equals("natural"))code=syllable.length()==2?syllable:syllable.substring(0,1)+f;else if(s.optString("zeroRule").equals("first-letter"))code=syllable.substring(0,1)+f;else code=s.optString("zeroKey","o")+f;part.add(code);}List<String> next=new ArrayList<>();for(String a:result)for(String b:part)if(next.size()<64)next.add(a+b);result=next;}return result;}
}
